<?php require '../includes/functions.php';require_role('super_admin');$rows=db()->query('SELECT a.*,u.full_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 300')->fetchAll();$pageTitle='Audit log';require '../includes/header.php';?><h1>Audit log</h1><table><tr><th>Date</th><th>Account</th><th>Action</th><th>Entity</th><th>Details</th><th>IP</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['full_name']??'Deleted account')?></td><td><?=e($r['action'])?></td><td><?=e($r['entity_type'])?> #<?=e((string)$r['entity_id'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach?></table><?php require '../includes/footer.php';?>
